/* Hover tooltip of {{Item}}: the item card opens beside the icon and name (tip=left: on the left side) */
.aa-itemtip {
  position: relative;
}
.aa-itemtip-card {
  display: none;
  position: absolute;
  top: -8px;
  left: 100%;
  z-index: 200;
  padding-left: 6px;   /* no gap, so the card stays open while the pointer moves onto it */
  width: 300px;
  max-width: 90vw;
  white-space: normal;
  font-weight: normal;
  font-style: normal;
  text-align: left;
  cursor: default;
}
.aa-itemtip-left .aa-itemtip-card {
  left: auto;
  right: 100%;
  padding-left: 0;
  padding-right: 6px;
}
.aa-itemtip:hover .aa-itemtip-card {
  display: block;
}
.aa-itemtip-card .aa-item {
  margin: 0;
}
/* Phones: no room beside the item, the card opens below it */
@media (max-width: 600px) {
  .aa-itemtip-card,
  .aa-itemtip-left .aa-itemtip-card {
    top: 100%;
    left: 0;
    right: auto;
    padding: 4px 0 0;
  }
}
